        if n in num2part:
            ctx[n].add((f,m.group(1).strip().lower()))
for n in sorted(num2part,key=int):
    print(n,'=',num2part[n])
    phrases=sorted({p for _,p in ctx[n]})
    for p in phrases: print('    ',p)
